import{_ as o,o as t,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"ADR-003 — RabbitMQ Direct & Tiered TTL-Retry Topology for Social Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"adr/adr-003-rabbitmq.md","filePath":"adr/adr-003-rabbitmq.md"}'),r={name:"adr/adr-003-rabbitmq.md"};function i(n,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="adr-003-—-rabbitmq-direct-tiered-ttl-retry-topology-for-social-publishing" tabindex="-1">ADR-003 — RabbitMQ Direct &amp; Tiered TTL-Retry Topology for Social Publishing <a class="header-anchor" href="#adr-003-—-rabbitmq-direct-tiered-ttl-retry-topology-for-social-publishing" aria-label="Permalink to &quot;ADR-003 — RabbitMQ Direct &amp; Tiered TTL-Retry Topology for Social Publishing&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← ADR Index</a> · <a href="/brandhub-infrastructure/view.html?file=architecture/rabbitmq-publisher-contract.html">RabbitMQ Contract</a> · <a href="./../architecture/service-boundaries.html">Service Boundaries</a> · <a href="./../architecture/sequence-diagrams.html">Sequence Diagrams</a></p><ul><li><strong>Status:</strong> Accepted</li><li><strong>Owners:</strong> Core Backend &amp; Social Integration Leads</li><li><strong>Related Docs:</strong> <a href="/brandhub-infrastructure/view.html?file=architecture/social-platforms-api-specs.html">Social Platforms API Specs</a> · <a href="./../ba/07-publishing-social.html">BA Publishing &amp; Social</a></li></ul><hr><h2 id="_1-context-problem-statement" tabindex="-1">1. Context &amp; Problem Statement <a class="header-anchor" href="#_1-context-problem-statement" aria-label="Permalink to &quot;1. Context &amp; Problem Statement&quot;">​</a></h2><p>Once a <code>Task</code> passes BrandHub&#39;s 3-tier approval sequence (<code>Creator -&gt; Manager -&gt; Client</code>, <code>FR 3.6.9</code>) and reaches either immediate publish (<code>FR 3.8.6</code>) or its scheduled timestamp (<code>FR 3.8.5</code>), the platform publishes content to <strong>strictly 4 supported social platforms</strong>:</p><ul><li><strong>Facebook</strong> (<code>FR 3.8.8</code> Page Post, <code>FR 3.8.9</code> Story, <code>FR 3.8.10</code> Reels — Meta Graph API <code>v19.0</code>)</li><li><strong>Instagram</strong> (<code>FR 3.8.11</code> Post/Carousel, <code>FR 3.8.12</code> Reels, <code>FR 3.8.13</code> Story — two-step Container Creation + Status Polling + Publish API)</li><li><strong>TikTok</strong> (<code>FR 3.8.14</code> Video — Content Posting API v2 chunked upload &amp; async transcode polling)</li><li><strong>Threads</strong> (<code>FR 3.8.15</code> Post — Threads Publishing container API)</li></ul><p>External platform APIs exhibit wide latency variance (<code>2</code>–<code>60+</code> seconds while Instagram/TikTok transcode video containers), strict per-app/per-account rate limits, and transient <code>5xx</code> outages. Blocking <code>brandhub-business-service</code> Tomcat threads on synchronous HTTP calls would exhaust connection pools during scheduled campaign bursts (e.g., <code>09:00</code> or <code>20:00</code> prime-time slots).</p><hr><h2 id="_2-evaluated-options" tabindex="-1">2. Evaluated Options <a class="header-anchor" href="#_2-evaluated-options" aria-label="Permalink to &quot;2. Evaluated Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Pros</th><th style="text-align:left;">Cons / Why Rejected or Selected</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Option A: Synchronous REST (<code>business-service</code> → <code>publisher-service</code>)</strong></td><td style="text-align:left;">Immediate HTTP status return</td><td style="text-align:left;">Blocks servlet threads up to 60s+ per video post; loses in-flight jobs if <code>publisher-service</code> restarts; no native backoff isolation</td></tr><tr><td style="text-align:left;"><strong>Option B: MongoDB Polling Queue (<code>posts.status = SCHEDULED</code>)</strong></td><td style="text-align:left;">Zero extra broker container</td><td style="text-align:left;">High polling read load; awkward multi-platform fan-out when one post targets 3 channels with independent retry schedules</td></tr><tr><td style="text-align:left;"><strong>Option C: Apache Kafka</strong></td><td style="text-align:left;">High-throughput log replay</td><td style="text-align:left;">Heavy JVM/KRaft memory footprint (<code>&gt; 1 GiB</code> RAM) disproportionate for <code>core</code> EC2 (<code>m7i-flex.large</code>, <code>8 GiB</code> total); lacks native per-message TTL delay queues</td></tr><tr><td style="text-align:left;"><strong>Option D: RabbitMQ 3.12 Direct + Dead-Letter TTL Retry Topology</strong> <em>(Selected)</em></td><td style="text-align:left;">Lightweight (<code>512m</code> RAM cap in prod), manual <code>ACK</code>/<code>NACK</code>, zero-code broker-enforced TTL delay queues (<code>1m</code>/<code>5m</code>/<code>15m</code>) + DLQ</td><td style="text-align:left;">Requires idempotency locks (<code>Redis</code>) in the consumer to prevent duplicate posts on redelivery</td></tr></tbody></table><hr><h2 id="_3-decision-architecture" tabindex="-1">3. Decision Architecture <a class="header-anchor" href="#_3-decision-architecture" aria-label="Permalink to &quot;3. Decision Architecture&quot;">​</a></h2><p>Decouple <code>brandhub-business-service</code> (<code>:8081</code>) and <code>brandhub-publisher-service</code> (<code>:8083</code>) via <strong>RabbitMQ 3.12</strong> (<code>rabbitmq:3.12-management-alpine</code>), paired with <strong>Redis</strong> per-(post, platform) idempotency locks and authenticated internal status callbacks:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brandhub-business-service (Scheduler / PostController.publish)</span></span>
<span class="line"><span>  │  Fan-out: 1 PublishJobMessage per target platform (AES-256 encrypted OAuth token + S3 media URLs)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>DirectExchange: publisher.job.exchange  ──(publisher.job.routing-key)──►  Queue: publisher.job.queue (durable, manual ACK)</span></span>
<span class="line"><span>                                                                                 │</span></span>
<span class="line"><span>                                                                                 ▼</span></span>
<span class="line"><span>                                                            brandhub-publisher-service (PublishJobConsumer)</span></span>
<span class="line"><span>                                                              ├─ 1. Acquire Redis lock: processingPostIds:{postId}:{platform} (TTL 30m)</span></span>
<span class="line"><span>                                                              ├─ 2. Decrypt token in memory (CryptoUtils AES-256-GCM / AES)</span></span>
<span class="line"><span>                                                              ├─ 3. Dispatch to SocialPublishAdapter (Facebook | Instagram | TikTok | Threads)</span></span>
<span class="line"><span>                                                              ├─ 4a. Success ──► basicAck + report DONE (platformPostId, permalink) to Business</span></span>
<span class="line"><span>                                                              ├─ 4b. Retryable error (attempt 1..3) ──► DirectExchange: publisher.retry.exchange</span></span>
<span class="line"><span>                                                              │        ├── publish.jobs.retry.1m  (TTL 60,000ms)  ─┐</span></span>
<span class="line"><span>                                                              │        ├── publish.jobs.retry.5m  (TTL 300,000ms) ─┼─► dead-letters back to publisher.job.exchange</span></span>
<span class="line"><span>                                                              │        └── publish.jobs.retry.15m (TTL 900,000ms) ─┘</span></span>
<span class="line"><span>                                                              └─ 4c. Non-retryable / Max retries exhausted ──► publisher.job.dlx ──► publisher.job.dlq + report FAIL</span></span></code></pre></div><p><em>(Note: RabbitMQ is also reused on <code>core</code> EC2 by <code>brandhub-crawl</code> → <code>brandhub-ai-service</code> <code>CrawlBatchConsumer</code> for asynchronous social trend batch ingestion.)</em></p><hr><h2 id="_4-real-codebase-infrastructure-grounding" tabindex="-1">4. Real Codebase &amp; Infrastructure Grounding <a class="header-anchor" href="#_4-real-codebase-infrastructure-grounding" aria-label="Permalink to &quot;4. Real Codebase &amp; Infrastructure Grounding&quot;">​</a></h2><ul><li><strong>Broker Configuration (<code>RabbitMQConfig.java</code> in <code>brandhub-publisher-service</code>)</strong>: <ul><li>Declares durable <code>publisher.job.queue</code> wired with <code>x-dead-letter-exchange = publisher.job.dlx</code> and <code>x-dead-letter-routing-key = publisher.job.dlq.routing-key</code> → durable <code>publisher.job.dlq</code>.</li><li>Declares <code>publisher.retry.exchange</code> bound to three durable TTL delay queues (<code>publish.jobs.retry.1m</code>, <code>publish.jobs.retry.5m</code>, <code>publish.jobs.retry.15m</code>) whose expired messages automatically route back to <code>publisher.job.exchange</code> with incremented <code>x-retry-count</code> headers.</li><li>Maps producer DTO type <code>com.brandhub.business.dto.message.PublishJobMessage</code> cleanly to consumer <code>com.brandhub.publisher.core.dto.PublishJobMessage</code> via <code>Jackson2JsonMessageConverter</code> + <code>DefaultClassMapper</code>.</li></ul></li><li><strong>Idempotent Consumer &amp; 4 Social Adapters (<code>PublishJobConsumer.java</code>)</strong>: <ul><li>Uses <code>acknowledge-mode: manual</code> (<code>spring.rabbitmq.listener.simple.retry.enabled: false</code>) so retry cadence is controlled deterministically by <code>ErrorClassifier</code> and the TTL delay queues.</li><li>Acquires a per-(post, platform) Redis lock <code>processingPostIds:{postId}:{platform}</code> (<code>Duration.ofMinutes(30)</code>) so multi-platform fan-out jobs for the same post execute concurrently while duplicate redeliveries for the same platform are suppressed.</li><li>Routes execution to <code>FacebookPublishAdapter</code>, <code>InstagramPublishAdapter</code>, <code>TikTokPublishAdapter</code>, or <code>ThreadsPublishAdapter</code> (<code>SocialPlatform</code> enum).</li></ul></li><li><strong>Proactive OAuth Token Refresh (<code>TokenRefreshScheduler</code> &amp; <code>SocialOAuthController</code>)</strong>: <ul><li><code>brandhub-publisher-service</code> runs a daily <code>02:00</code> cron (<code>TOKEN_REFRESH_CRON=&quot;0 0 2 * * ?&quot;</code>, <code>threshold-days: 7</code>) querying <code>GET /api/v1/internal/social-accounts/expiring</code> on <code>business-service</code>, refreshing expiring Meta/TikTok/Threads tokens, and syncing encrypted tokens back via <code>POST /api/v1/internal/social-accounts/sync</code> (<code>X-Internal-Key</code>).</li></ul></li></ul><hr><h2 id="_5-trade-offs-operational-impact" tabindex="-1">5. Trade-offs &amp; Operational Impact <a class="header-anchor" href="#_5-trade-offs-operational-impact" aria-label="Permalink to &quot;5. Trade-offs &amp; Operational Impact&quot;">​</a></h2><h3 id="positive-outcomes" tabindex="-1">Positive Outcomes <a class="header-anchor" href="#positive-outcomes" aria-label="Permalink to &quot;Positive Outcomes&quot;">​</a></h3><ul><li><strong>Zero HTTP Thread Starvation</strong>: <code>business-service</code> enqueues <code>PublishJobMessage</code> in <code>&lt; 5 ms</code> regardless of Instagram/TikTok video container processing times.</li><li><strong>Per-Platform Fault Isolation</strong>: If TikTok&#39;s API returns <code>503</code> while Facebook succeeds for the same multi-channel campaign post, only the TikTok job enters <code>publish.jobs.retry.1m</code> -&gt; <code>5m</code> -&gt; <code>15m</code> without re-publishing to Facebook.</li><li><strong>Stateless Database Boundary</strong>: <code>publisher-service</code> requires zero credentials to PostgreSQL or business MongoDB collections (owning only <code>publish_logs</code>).</li></ul><h3 id="accepted-costs-mitigations" tabindex="-1">Accepted Costs &amp; Mitigations <a class="header-anchor" href="#accepted-costs-mitigations" aria-label="Permalink to &quot;Accepted Costs &amp; Mitigations&quot;">​</a></h3><ul><li><strong>Eventual UI Status (<code>PENDING</code> / <code>IN_PROGRESS</code> → <code>PUBLISHED</code> / <code>FAILED</code>)</strong>: Users observe asynchronous status transitions (<code>FR 3.8.7 Track Post Status</code>) and receive real-time in-app notifications (<code>user_notifications</code> STOMP push) when publishing completes or exhausts retries.</li><li><strong>DLQ Monitoring</strong>: Poison or permanently rejected payloads accumulate in <code>publisher.job.dlq</code> and are surfaced through <code>Admin</code> System Health Monitoring (<code>FR 3.10.3</code>).</li></ul>`,25)])])}const b=o(r,[["render",i]]);export{h as __pageData,b as default};
